<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  html,body { width:100%; height:100%; overflow:hidden; background:#0b1020; font-family:'Segoe UI',system-ui,sans-serif; }
  #wrap { position:fixed; inset:0; display:flex; align-items:center; justify-content:center; }
  canvas { display:block; background:#0b1020; touch-action:none; }
  #ui { position:absolute; inset:0; pointer-events:none; }
  .overlay { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center;
    background:linear-gradient(160deg,rgba(30,58,138,.95),rgba(14,116,144,.95)); color:#fff; text-align:center; padding:20px; pointer-events:auto; }
  .overlay h1 { font-size:clamp(20px,4vw,38px); margin-bottom:10px; text-shadow:0 2px 12px rgba(0,0,0,.5); }
  .overlay p { font-size:clamp(12px,1.8vw,16px); max-width:600px; margin-bottom:8px; line-height:1.5; opacity:.95; }
  .btn { margin-top:16px; padding:12px 28px; font-size:clamp(14px,2vw,18px); font-weight:700; border:none; border-radius:30px;
    background:linear-gradient(135deg,#22d3ee,#3b82f6); color:#fff; cursor:pointer; box-shadow:0 6px 20px rgba(34,211,238,.4); transition:transform .15s; }
  .btn:active { transform:scale(.95); }
  .wm { position:absolute; bottom:10px; font-size:11px; opacity:.6; letter-spacing:.5px; }
  #muteBtn { position:absolute; top:12px; right:12px; width:44px; height:44px; border-radius:50%; border:none;
    background:rgba(255,255,255,.15); color:#fff; font-size:20px; cursor:pointer; pointer-events:auto; backdrop-filter:blur(4px); }
  .hidden { display:none !important; }
  #touch { position:absolute; inset:0; pointer-events:none; }
  .tbtn { position:absolute; bottom:24px; width:70px; height:70px; border-radius:50%; border:2px solid rgba(255,255,255,.4);
    background:rgba(255,255,255,.12); color:#fff; font-size:26px; pointer-events:auto; backdrop-filter:blur(4px); user-select:none; }
  .tbtn:active { background:rgba(255,255,255,.3); }
  #tLeft { left:20px; } #tRight { left:110px; } #tJump { right:20px; width:84px; height:84px; font-size:30px; }
  #tSlow { right:120px; width:64px; height:64px; font-size:14px; font-weight:700; }
