<body>
<div id="wrap">
  <canvas id="cv"></canvas>
  <div id="ui">
    <button id="muteBtn">🔊</button>
    <div id="touch" class="hidden">
      <button class="tbtn" id="tLeft">◀</button>
      <button class="tbtn" id="tRight">▶</button>
      <button class="tbtn" id="tJump">⤒</button>
      <button class="tbtn" id="tSlow">LAMBAT</button>
    </div>
    <div class="overlay" id="startScreen">
      <h1>🌟 Gravitasi Rani</h1>
      <p><b>Reaktor yang Hilang</b></p>
      <p>Lompat antar platform dan kumpulkan <b>contoh energi potensial</b> (benda di ketinggian). Kumpulkan 10 yang benar untuk menang!</p>
      <p style="font-size:12px;opacity:.8">Kontrol: ← → / A D untuk gerak · Spasi / ↑ untuk lompat · Shift untuk gravitasi lambat</p>
      <button class="btn" id="startBtn">Mulai Bermain</button>
      <div class="wm">Built with AISYS HTML5 Engine · STIKOM YOS SUDARSO</div>
    </div>
    <div class="overlay hidden" id="endScreen">
      <h1 id="endTitle">Selesai!</h1>
      <p id="endMsg"></p>
      <button class="btn" id="againBtn">Main Lagi</button>
      <div class="wm">Built with AISYS HTML5 Engine · STIKOM YOS SUDARSO</div>
    </div>
  </div>
</div>
<script>
(function(){
"use strict";

// ===== AUDIO =====
let actx=null, muted=false;
function unlockAudio(){ if(!actx){ try{ actx=new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} } if(actx&&actx.state==="suspended") actx.resume(); }
function beep(freq,dur,type,vol){ if(!actx||muted) return; const o=actx.createOscillator(),g=actx.createGain();
  o.type=type||"sine"; o.frequency.value=freq; g.gain.value=vol||0.08; o.connect(g); g.connect(actx.destination);
  const t=actx.currentTime; g.gain.setValueAtTime(g.gain.value,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  o.start(t); o.stop(t+dur); }
const sfx={ correct(){beep(880,.12,"sine",.1);setTimeout(()=>beep(1320,.15,"sine",.08),80);},
  wrong(){beep(180,.25,"sawtooth",.09);}, jump(){beep(520,.1,"square",.05);}, win(){[523,659,784,1046].forEach((f,i)=>setTimeout(()=>beep(f,.2,"sine",.09),i*120));},
  lose(){[400,300,200].forEach((f,i)=>setTimeout(()=>beep(f,.25,"sawtooth",.08),i*150));} };

// ===== CANVAS =====
const cv=document.getElementById("cv"), ctx=cv.getContext("2d");
let W=960,H=540, scale=1;
function resize(){ const ww=window.innerWidth, wh=window.innerHeight; const ar=16/9;
  if(ww/wh>ar){ H=wh; W=wh*ar; } else { W=ww; H=ww/ar; }
  cv.width=W; cv.height=H; cv.style.width=W+"px"; cv.style.height=H+"px"; }
window.addEventListener("resize",resize); resize();

// ===== DATA SOAL (contoh konkret) =====
const BANK=[
  {t:"Bola menggelinding di lantai", a:"kinetik", e:"Benda bergerak punya energi kinetik."},
  {t:"Buku di atas rak tinggi", a:"potensial", e:"Benda di ketinggian menyimpan energi potensial."},
  {t:"Air terjun jatuh ke bawah", a:"kinetik", e:"Air yang bergerak cepat punya energi kinetik."},
  {t:"Buah mangga di dahan pohon", a:"potensial", e:"Posisi tinggi memberi energi potensial gravitasi."},
  {t:"Mobil melaju di jalan", a:"kinetik", e:"Massa yang bergerak memiliki energi kinetik."},
  {t:"Batu di tepi jurang", a:"potensial", e:"Belum jatuh, tapi posisinya tinggi: energi potensial."},
  {t:"Anak panah melesat dari busur", a:"kinetik", e:"Anak panah bergerak cepat: energi kinetik."},
  {t:"Vas bunga di atas lemari", a:"potensial", e:"Berada di ketinggian, menyimpan energi potensial."},
  {t:"Benda diam di lantai", a:"kinetik", e:"Jebakan! Benda diam di lantai tidak punya energi potensial berarti."},
  {t:"Kereta roller coaster di puncak", a:"potensial", e:"Di titik tertinggi, energi potensialnya paling besar."}
];
const TARGET="potensial";

// ===== GAME STATE =====
let state="menu", camX=0, score=0, lives=3, correctCount=0, slowTimer=0, slowCd=0;
let particles=[], floaters=[], platforms=[], coins=[], hazards=[], player=null, keys={}, lastTime=0, feedback=null, feedbackT=0;
const GRAV=1800, JUMP=-720, SPEED=280, SLOW_GRAV=500;

function resetGame(){
  state="play"; camX=0; score=0; lives=3; correctCount=0; slowTimer=0; slowCd=0;
  particles=[]; floaters=[]; feedback=null; feedbackT=0;
  player={x:120,y:300,vx:0,vy:0,w:36,h:48,onGround:false,face:1};
  platforms=[]; coins=[]; hazards=[];
  // platform awal
  platforms.push({x:0,y:440,w:260,h:100});
  let px=300, py=440;
  const shuffled=[...BANK].sort(()=>Math.random()-0.5);
  for(let i=0;i<14;i++){
    const gap=90+Math.random()*70;
    const dy=(Math.random()-0.5)*140;
    py=Math.max(200,Math.min(470,py+dy));
    const pw=120+Math.random()*90;
    platforms.push({x:px,y:py,w:pw,h:100});
    // koin di atas platform
    const item=shuffled[i%BANK.length];
    coins.push({x:px+pw/2-16,y:py-70,w:32,h:32,item:item,got:false,bob:Math.random()*6});
    // rintangan (drone) di celah
    if(i>1 && Math.random()<0.6){
      hazards.push({x:px-gap/2,y:py-40,w:34,h:34,base:py-40,phase:Math.random()*6});
    }
    px+=pw+gap;
  }
  // koin tambahan
  for(let i=0;i<6;i++){
    const item=shuffled[(i+7)%BANK.length];
    const p=platforms[2+Math.floor(Math.random()*(platforms.length-2))];
    coins.push({x:p.x+p.w*0.3+Math.random()*p.w*0.4,y:p.y-100,w:32,h:32,item:item,got:false,bob:Math.random()*6});
  }
}

// ===== INPUT =====
document.addEventListener("keydown",e=>{
  if(["ArrowLeft","ArrowRight","ArrowUp"," ","Space"].includes(e.key)) e.preventDefault();
  keys[e.key.toLowerCase()]=true; unlockAudio();
  if(e.key===" "||e.key==="ArrowUp"){ if(state==="play") doJump(); }
  if(e.key==="Shift"){ if(state==="play") doSlow(); }
});
document.addEventListener("keyup",e=>{ keys[e.key.toLowerCase()]=false; });

function doJump(){ if(player&&player.onGround){ player.vy=JUMP; player.onGround=false; sfx.jump(); } }
function doSlow(){ if(slowCd<=0){ slowTimer=1.2; slowCd=3; } }

// touch
const touchDiv=document.getElementById("touch");
if("ontouchstart" in window) touchDiv.classList.remove("hidden");
function bindHold(id,down,up){ const el=document.getElementById(id);
  el.addEventListener("touchstart",e=>{e.preventDefault();unlockAudio();down();},{passive:false});
  el.addEventListener("touchend",e=>{e.preventDefault();if(up)up();},{passive:false});
  el.addEventListener("mousedown",e=>{e.preventDefault();unlockAudio();down();});
  el.addEventListener("mouseup",e=>{e.preventDefault();if(up)up();});
}
bindHold("tLeft",()=>keys["arrowleft"]=true,()=>keys["arrowleft"]=false);
bindHold("tRight",()=>keys["arrowright"]=true,()=>keys["arrowright"]=false);
bindHold("tJump",()=>{if(state==="play")doJump();});
bindHold("tSlow",()=>{if(state==="play")doSlow();});

// ===== UPDATE =====
function update(dt){
  if(state!=="play") return;
  if(slowTimer>0) slowTimer-=dt;
  if(slowCd>0) slowCd-=dt;
  const g=slowTimer>0?SLOW_GRAV:GRAV;
  // gerak horizontal
  let mv=0;
  if(keys["arrowleft"]||keys["a"]) mv-=1;
  if(keys["arrowright"]||keys["d"]) mv+=1;
  if(mv!==0) player.face=mv;
  player.vx=mv*SPEED;
  player.x+=player.vx*dt;
  if(player.x<0) player.x=0;
  // gravitasi
  player.vy+=g*dt;
  player.y+=player.vy*dt;
  player.onGround=false;
  // tabrakan platform
  for(const p of platforms){
    if(player.x+player.w>p.x && player.x<p.x+p.w){
      if(player.vy>=0 && player.y+player.h>p.y && player.y+player.h<p.y+p.h+30 && player.vy>0){
        player.y=p.y-player.h; player.vy=0; player.onGround=true;
      }
    }
  }
  // jatuh ke bawah
  if(player.y>H+200){ hitHazard(true); }
  // kamera
  const targetCam=player.x-W*0.35;
  camX+=(targetCam-camX)*Math.min(1,dt*6);
  if(camX<0) camX=0;
  // koin
  for(const c of coins){
    if(c.got) continue;
    c.bob+=dt*3;
    if(Math.abs((player.x+player.w/2)-(c.x+c.w/2))<30 && Math.abs((player.y+player.h/2)-(c.y+c.h/2))<38){
      c.got=true; collect(c);
    }
  }
  // rintangan
  for(const h of hazards){
    h.phase+=dt*2;
    if(Math.abs((player.x+player.w/2)-(h.x+h.w/2))<32 && Math.abs((player.y+player.h/2)-(h.y+h.h/2))<34){
      hitHazard(false);
    }
  }
  // partikel
  for(let i=particles.length-1;i>=0;i--){ const p=particles[i]; p.x+=p.vx*dt; p.y+=p.vy*dt; p.vy+=600*dt; p.life-=dt; if(p.life<=0) particles.splice(i,1); }
  for(let i=floaters.length-1;i>=0;i--){ const f=floaters[i]; f.y-=40*dt; f.life-=dt; if(f.life<=0) floaters.splice(i,1); }
  if(feedbackT>0) feedbackT-=dt;
}

function collect(c){
  const isCorrect = c.item.a===TARGET;
  if(isCorrect){
    correctCount++; score+=100; sfx.correct();
    spawnParticles(c.x+16,c.y+16,"#22d3ee",14);
    floaters.push({x:c.x,y:c.y,text:"+100",life:1,color:"#22d3ee"});
    feedback={text:"✓ "+c.item.e,ok:true}; feedbackT=2;
    if(correctCount>=10){ winGame(); }
  } else {
    score=Math.max(0,score-30); lives--; sfx.wrong();
    spawnParticles(c.x+16,c.y+16,"#ef4444",10);
    floaters.push({x:c.x,y:c.y,text:"-30",life:1,color:"#ef4444"});
    feedback={text:"✗ "+c.item.e,ok:false}; feedbackT=2;
    if(lives<=0) loseGame();
  }
}

function hitHazard(fell){
  if(slowTimer>0 && !fell) return; // gravitasi lambat = kebal sebentar
  lives--; sfx.wrong();
  spawnParticles(player.x+18,player.y+24,"#f59e0b",12);
  feedback={text:"Awas drone Profesor Entropi!",ok:false}; feedbackT=1.5;
  if(fell){ player.x=Math.max(0,player.x-60); player.y=200; player.vy=0; }
  else { player.vy=-400; player.x-=40; }
  if(lives<=0) loseGame();
}

function spawnParticles(x,y,color,n){
  for(let i=0;i<n;i++){ const a=Math.random()*Math.PI*2, s=80+Math.random()*180;
    particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-100,life:0.6+Math.random()*0.4,color}); }
}

function winGame(){ state="end"; sfx.win(); showEnd(true); }
function loseGame(){ state="end"; sfx.lose(); showEnd(false); }

// ===== DRAW =====
function draw(){
  // background gradient
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,"#1e3a8a"); bg.addColorStop(1,"#0e7490");
  ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);
  // bintang/lampu lab
  ctx.save();
  for(let i=0;i<40;i++){
    const sx=((i*137)%W), sy=((i*89)%(H*0.5));
    ctx.globalAlpha=0.3+0.3*Math.sin(performance.now()/800+i);
    ctx.fillStyle="#a5f3fc"; ctx.beginPath(); ctx.arc(sx,sy,1.5,0,7); ctx.fill();
  }
  ctx.restore();
  // lantai lab
  ctx.fillStyle="rgba(15,23,42,.6)"; ctx.fillRect(0,H-40,W,40);
  ctx.strokeStyle="rgba(34,211,238,.3)"; ctx.lineWidth=2;
  for(let x=-camX%80;x<W;x+=80){ ctx.beginPath(); ctx.moveTo(x,H-40); ctx.lineTo(x,H); ctx.stroke(); }

  ctx.save();
  ctx.translate(-camX,0);

  // platform
  for(const p of platforms){
    if(p.x+p.w<camX-50||p.x>camX+W+50) continue;
    const pg=ctx.createLinearGradient(0,p.y,0,p.y+p.h);
    pg.addColorStop(0,"#334155"); pg.addColorStop(1,"#1e293b");
    ctx.fillStyle=pg;
    roundRect(p.x,p.y,p.w,p.h,10); ctx.fill();
    ctx.strokeStyle="rgba(34,211,238,.6)"; ctx.lineWidth=2;
    roundRect(p.x,p.y,p.w,p.h,10); ctx.stroke();
    // garis atas
    ctx.fillStyle="rgba(34,211,238,.25)"; ctx.fillRect(p.x+6,p.y+3,p.w-12,4);
  }

  // koin
  for(const c of coins){
    if(c.got) continue;
    if(c.x+c.w<camX-50||c.x>camX+W+50) continue;
    const by=Math.sin(c.bob)*4;
    const cg=ctx.createRadialGradient(c.x+16,c.y+16+by,2,c.x+16,c.y+16+by,20);
    cg.addColorStop(0,"#fef08a"); cg.addColorStop(1,"#f59e0b");
    ctx.save(); ctx.shadowColor="#fbbf24"; ctx.shadowBlur=14;
    ctx.fillStyle=cg; ctx.beginPath(); ctx.arc(c.x+16,c.y+16+by,16,0,7); ctx.fill();
    ctx.restore();
    ctx.fillStyle="#78350f"; ctx.font="bold 11px sans-serif"; ctx.textAlign="center";
    ctx.fillText("?",c.x+16,c.y+20+by);
  }

  // rintangan drone
  for(const h of hazards){
    if(h.x+h.w<camX-50||h.x>camX+W+50) continue;
    const hy=h.base+Math.sin(h.phase)*14;
    ctx.save(); ctx.shadowColor="#ef4444"; ctx.shadowBlur=12;
    ctx.fillStyle="#dc2626"; ctx.beginPath(); ctx.arc(h.x+17,hy+17,17,0,7); ctx.fill();
    ctx.restore();
    ctx.fillStyle="#7f1d1d"; ctx.beginPath(); ctx.arc(h.x+17,hy+17,8,0,7); ctx.fill();
    ctx.fillStyle="#fca5a5"; ctx.beginPath(); ctx.arc(h.x+12,hy+13,3,0,7); ctx.fill();
    ctx.beginPath(); ctx.arc(h.x+22,hy+13,3,0,7); ctx.fill();
  }

  // player Rani
  drawRani(player.x,player.y);

  // partikel
  for(const p of particles){ ctx.globalAlpha=Math.max(0,p.life); ctx.fillStyle=p.color; ctx.beginPath(); ctx.arc(p.x,p.y,3,0,7); ctx.fill(); }
  ctx.globalAlpha=1;

  // floaters
  for(const f of floaters){ ctx.globalAlpha=Math.max(0,f.life); ctx.fillStyle=f.color; ctx.font="bold 16px sans-serif"; ctx.textAlign="center"; ctx.fillText(f.text,f.x+16,f.y); }
  ctx.globalAlpha=1;

  ctx.restore();

  // HUD
  drawHUD();
}

function drawRani(x,y){
  ctx.save();
  // aura gravitasi
  if(slowTimer>0){ ctx.save(); ctx.globalAlpha=0.4; ctx.strokeStyle="#a5f3fc"; ctx.lineWidth=3;
    ctx.beginPath(); ctx.arc(x+18,y+24,34+Math.sin(performance.now()/100)*4,0,7); ctx.stroke(); ctx.restore(); }
  // badan
  const bg=ctx.createLinearGradient(x,y,x,y+48);
  bg.addColorStop(0,"#38bdf8"); bg.addColorStop(1,"#1d4ed8");
  ctx.fillStyle=bg; roundRect(x+4,y+16,28,30,8); ctx.fill();
  // kepala
  ctx.fillStyle="#fcd9b6"; ctx.beginPath(); ctx.arc(x+18,y+12,12,0,7); ctx.fill();
  // rambut
  ctx.fillStyle="#1e293b"; ctx.beginPath(); ctx.arc(x+18,y+8,12,Math.PI,0); ctx.fill();
  ctx.fillRect(x+6,y+8,24,6);
  // mata
  ctx.fillStyle="#0f172a"; ctx.beginPath(); ctx.arc(x+14,y+13,2,0,7); ctx.fill(); ctx.beginPath(); ctx.arc(x+22,y+13,2,0,7); ctx.fill();
  // senyum
  ctx.strokeStyle="#b45309"; ctx.lineWidth=1.5; ctx.beginPath(); ctx.arc(x+18,y+16,4,0.2,Math.PI-0.2); ctx.stroke();
  // kaki
  ctx.fillStyle="#1e3a8a"; ctx.fillRect(x+8,y+44,8,6); ctx.fillRect(x+20,y+44,8,6);
  ctx.restore();
}

function roundRect(x,y,w,h,r){ ctx.beginPath(); ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r); ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath(); }

function drawHUD(){
  ctx.save();
  // panel atas
  ctx.fillStyle="rgba(15,23,42,.7)"; roundRect(12,12,300,64,12); ctx.fill();
  ctx.fillStyle="#fff"; ctx.font="bold 15px sans-serif"; ctx.textAlign="left";
  ctx.fillText("🎯 Target: "+TARGET.toUpperCase(),24,36);
  ctx.fillStyle="#22d3ee"; ctx.fillText("Benar: "+correctCount+"/10",24,58);
  // nyawa
  ctx.textAlign="right"; ctx.fillStyle="#fff"; ctx.font="bold 15px sans-serif";
  ctx.fillText("❤️".repeat(Math.max(0,lives)),W-70,36);
  ctx.fillStyle="#fbbf24"; ctx.fillText("Skor: "+score,W-70,58);
  // slow cooldown
  ctx.textAlign="left"; ctx.font="12px sans-serif";
  ctx.fillStyle=slowCd<=0?"#22d3ee":"#64748b";
  ctx.fillText(slowCd<=0?"⚡ Gravitasi Lambat SIAP":"⚡ Lambat: "+slowCd.toFixed(1)+"s",24,90);
  // feedback
  if(feedbackT>0&&feedback){
    ctx.textAlign="center"; ctx.font="bold 16px sans-serif";
    const fw=Math.min(W-40,ctx.measureText(feedback.text).width+40);
    ctx.fillStyle=feedback.ok?"rgba(16,185,129,.9)":"rgba(239,68,68,.9)";
    roundRect(W/2-fw/2,H-90,fw,44,12); ctx.fill();
    ctx.fillStyle="#fff"; ctx.fillText(feedback.text,W/2,H-62);
  }
  // watermark
  ctx.globalAlpha=0.35; ctx.fillStyle="#fff"; ctx.font="11px sans-serif"; ctx.textAlign="right";
  ctx.fillText("AISYS HTML5 Engine",W-16,H-16);
  ctx.restore();
}

// ===== LOOP =====
function loop(t){
  const dt=Math.min(0.05,(t-lastTime)/1000||0); lastTime=t;
  update(dt); draw();
  requestAnimationFrame(loop);
}

// ===== UI =====
const startScreen=document.getElementById("startScreen"), endScreen=document.getElementById("endScreen");
const endTitle=document.getElementById("endTitle"), endMsg=document.getElementById("endMsg");
document.getElementById("startBtn").addEventListener("click",()=>{ unlockAudio(); startScreen.classList.add("hidden"); resetGame(); });
document.getElementById("againBtn").addEventListener("click",()=>{ endScreen.classList.add("hidden"); resetGame(); });
document.getElementById("muteBtn").addEventListener("click",()=>{ muted=!muted; document.getElementById("muteBtn").textContent=muted?"🔇":"🔊"; });

function showEnd(win){
  endTitle.textContent=win?"🏆 Menang!":"💫 Coba Lagi";
  endMsg.textContent=win?"Rani mengembalikan reaktor dan gurunya sadar. Lab bersinar lagi!":"Reaktor masih hilang, tapi Rani tidak menyerah. Kamu pasti bisa!";
  endScreen.classList.remove("hidden");
  if(window.AISYS&&AISYS.end) AISYS.end(win?"menang":"kalah");
}

requestAnimationFrame(loop);
})();
</script>
